import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { shopApi } from '../api/shop';
import { Pagination } from '../types';
import { useAuth } from '../context/AuthContext';
import {
  Boxes,
  Plus,
  Edit2,
  RefreshCw,
  Loader2,
  AlertCircle,
  CheckCircle2,
  X,
  ArrowLeft,
  Info,
  Archive,
  Eye,
  Layers,
} from 'lucide-react';

interface CategoryItem {
  _id: string;
  name: string;
  slug?: string;
  description?: string;
  status?: 'draft' | 'published' | 'archived';
  sortOrder?: number;
  parentId?: string;
}

export const AdminCategories: React.FC = () => {
  const { hasRole } = useAuth();
  const canManage = hasRole(['admin', 'super_admin', 'moderator', 'creator', 'developer']);

  const [categories, setCategories] = useState<CategoryItem[]>([]);
  const [pagination, setPagination] = useState<Pagination>({
    page: 1,
    limit: 50,
    total: 0,
    totalPages: 1,
  });
  const [statusFilter, setStatusFilter] = useState<string>('');
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [actionSuccess, setActionSuccess] = useState<string | null>(null);

  // Modal State
  const [modalMode, setModalMode] = useState<'create' | 'edit' | null>(null);
  const [editingCategory, setEditingCategory] = useState<CategoryItem | null>(null);
  const [categoryForm, setCategoryForm] = useState({
    name: '',
    slug: '',
    description: '',
    status: 'published' as 'draft' | 'published' | 'archived',
    sortOrder: 0,
    parentId: '',
  });
  const [submittingModal, setSubmittingModal] = useState(false);
  const [modalError, setModalError] = useState<string | null>(null);

  const fetchCategories = async (targetPage = 1) => {
    setLoading(true);
    setError(null);
    try {
      const res = await shopApi.getCategories({
        page: targetPage,
        limit: pagination.limit,
        status: statusFilter || undefined,
      });
      setCategories(res.categories);
      setPagination(res.pagination);
    } catch (err: any) {
      setError(err?.error || err?.message || 'Failed to load store categories.');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchCategories(1);
  }, [statusFilter]);

  const openCreateModal = () => {
    setModalMode('create');
    setEditingCategory(null);
    setCategoryForm({
      name: '',
      slug: '',
      description: '',
      status: 'published',
      sortOrder: categories.length * 10,
      parentId: '',
    });
    setModalError(null);
  };

  const openEditModal = (c: CategoryItem) => {
    setModalMode('edit');
    setEditingCategory(c);
    setCategoryForm({
      name: c.name || '',
      slug: c.slug || '',
      description: c.description || '',
      status: c.status || 'published',
      sortOrder: c.sortOrder ?? 0,
      parentId: c.parentId || '',
    });
    setModalError(null);
  };

  const handleSaveCategory = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!categoryForm.name.trim()) {
      setModalError('Category name is required (2-80 characters).');
      return;
    }

    setSubmittingModal(true);
    setModalError(null);
    try {
      if (modalMode === 'create') {
        await shopApi.createCategory({
          name: categoryForm.name.trim(),
          slug: categoryForm.slug.trim() || undefined,
          description: categoryForm.description.trim() || undefined,
          status: categoryForm.status,
          sortOrder: Number(categoryForm.sortOrder) || 0,
          parentId: categoryForm.parentId.trim() || undefined,
        });
        setActionSuccess(`Category "${categoryForm.name}" created successfully.`);
      } else if (modalMode === 'edit' && editingCategory) {
        await shopApi.updateCategory(editingCategory._id, {
          name: categoryForm.name.trim(),
          slug: categoryForm.slug.trim() || undefined,
          description: categoryForm.description.trim() || undefined,
          status: categoryForm.status,
          sortOrder: Number(categoryForm.sortOrder) || 0,
          parentId: categoryForm.parentId.trim() || undefined,
        });
        setActionSuccess(`Category "${categoryForm.name}" updated successfully.`);
      }
      setModalMode(null);
      await fetchCategories(pagination.page);
    } catch (err: any) {
      setModalError(err?.error || err?.message || 'Failed to save category.');
    } finally {
      setSubmittingModal(false);
    }
  };

  return (
    <div className="max-w-6xl mx-auto px-4 py-12">
      {/* Navigation */}
      <div className="mb-6">
        <Link
          to="/admin"
          className="inline-flex items-center gap-1.5 text-xs font-semibold text-slate-500 hover:text-slate-900 dark:hover:text-white transition-colors"
        >
          <ArrowLeft size={13} />
          <span>Back to Operations Hub</span>
        </Link>
      </div>

      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-8 pb-6 border-b border-slate-200 dark:border-slate-800">
        <div>
          <div className="flex items-center gap-2">
            <span className="text-[11px] font-mono uppercase tracking-wider text-teal-600 dark:text-teal-400 font-bold">
              CATALOG TAXONOMY
            </span>
            <span className="text-xs text-slate-400">·</span>
            <span className="text-xs text-slate-500 dark:text-slate-400">
              Taxonomy Structure
            </span>
          </div>
          <h1 className="font-display text-2xl sm:text-3xl font-bold text-slate-900 dark:text-white mt-1">
            Category Management
          </h1>
          <p className="text-xs sm:text-sm text-slate-500 dark:text-slate-400 mt-1">
            Organize catalog releases into hierarchical categories and manage storefront visibility.
          </p>
        </div>

        <div className="flex items-center gap-3">
          <button
            type="button"
            onClick={() => fetchCategories(pagination.page)}
            disabled={loading}
            className="px-3.5 py-2 rounded-xl border border-slate-200 dark:border-slate-800 hover:bg-slate-100 dark:hover:bg-slate-900 text-xs font-semibold text-slate-700 dark:text-slate-300 inline-flex items-center gap-1.5 transition-colors"
          >
            <RefreshCw size={13} className={loading ? 'animate-spin' : ''} />
            <span>Refresh</span>
          </button>
          {canManage && (
            <button
              type="button"
              onClick={openCreateModal}
              className="px-4 py-2 rounded-xl bg-teal-600 hover:bg-teal-500 text-white text-xs font-semibold inline-flex items-center gap-1.5 transition-colors shadow-lg shadow-teal-950/20"
            >
              <Plus size={14} />
              <span>New Category</span>
            </button>
          )}
        </div>
      </div>

      {/* Backend Gap / Deletion Limitation Flag */}
      <div className="mb-6 p-4 rounded-2xl bg-amber-500/5 border border-amber-500/20 text-xs text-slate-600 dark:text-slate-300 flex items-start gap-3">
        <Info size={16} className="text-amber-500 shrink-0 mt-0.5" />
        <div className="space-y-1">
          <p className="font-semibold text-slate-900 dark:text-white">
            Backend Deletion Limitation
          </p>
          <p className="text-slate-500 dark:text-slate-400 leading-relaxed">
            Per backend contract, category deletion is unsupported (no delete endpoint exists in the API).
            To remove a category from public storefront navigation, edit its status to{' '}
            <span className="font-mono font-semibold text-slate-700 dark:text-slate-300">archived</span> or{' '}
            <span className="font-mono font-semibold text-slate-700 dark:text-slate-300">draft</span>.
          </p>
        </div>
      </div>

      {actionSuccess && (
        <div className="mb-6 p-4 rounded-xl bg-emerald-500/10 border border-emerald-500/20 text-emerald-600 dark:text-emerald-400 text-xs flex items-center justify-between">
          <div className="flex items-center gap-2">
            <CheckCircle2 size={16} />
            <span>{actionSuccess}</span>
          </div>
          <button
            type="button"
            onClick={() => setActionSuccess(null)}
            className="text-emerald-700 dark:text-emerald-300 hover:opacity-75"
          >
            <X size={14} />
          </button>
        </div>
      )}

      {/* Filter toolbar */}
      <div className="p-4 rounded-2xl bg-white dark:bg-[#101216] border border-slate-200 dark:border-slate-800 shadow-sm mb-6 flex items-center gap-3">
        <span className="text-xs font-mono uppercase tracking-wider text-slate-500">Status:</span>
        <div className="flex items-center gap-2">
          {['', 'published', 'draft', 'archived'].map(s => (
            <button
              key={s || 'all'}
              type="button"
              onClick={() => setStatusFilter(s)}
              className={`px-3 py-1.5 rounded-lg text-xs font-semibold transition-colors ${
                statusFilter === s
                  ? 'bg-teal-600 text-white'
                  : 'bg-slate-100 dark:bg-slate-900 text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white'
              }`}
            >
              {s ? s.charAt(0).toUpperCase() + s.slice(1) : 'All Statuses'}
            </button>
          ))}
        </div>
      </div>

      {/* Error state */}
      {error && (
        <div className="p-6 rounded-2xl bg-rose-500/10 border border-rose-500/20 text-rose-600 dark:text-rose-400 text-xs mb-6 flex items-center gap-3">
          <AlertCircle size={18} />
          <span>{error}</span>
        </div>
      )}

      {/* Category List */}
      {loading ? (
        <div className="py-24 text-center">
          <Loader2 size={32} className="animate-spin text-teal-500 mx-auto mb-3" />
          <p className="text-xs font-mono text-slate-500">Loading categories...</p>
        </div>
      ) : categories.length === 0 ? (
        <div className="py-20 text-center rounded-3xl bg-white dark:bg-[#101216] border border-slate-200 dark:border-slate-800">
          <Boxes size={36} className="text-slate-400 mx-auto mb-3" />
          <h2 className="font-display text-base font-bold text-slate-900 dark:text-white mb-1">
            No Categories Found
          </h2>
          <p className="text-xs text-slate-500 dark:text-slate-400 max-w-sm mx-auto mb-4">
            Create your first taxonomy category to group store products, bundles, and courses.
          </p>
          {canManage && (
            <button
              type="button"
              onClick={openCreateModal}
              className="px-4 py-2 rounded-xl bg-teal-600 text-white text-xs font-semibold"
            >
              Create Category
            </button>
          )}
        </div>
      ) : (
        <div className="space-y-4">
          <div className="rounded-2xl bg-white dark:bg-[#101216] border border-slate-200 dark:border-slate-800 shadow-sm overflow-hidden">
            <div className="overflow-x-auto">
              <table className="w-full text-left text-xs">
                <thead>
                  <tr className="border-b border-slate-200 dark:border-slate-800 bg-slate-50/50 dark:bg-slate-900/50 text-slate-500 font-mono uppercase tracking-wider text-[11px]">
                    <th className="py-3 px-4">Name</th>
                    <th className="py-3 px-4">Slug</th>
                    <th className="py-3 px-4">Status</th>
                    <th className="py-3 px-4 font-mono">Order</th>
                    <th className="py-3 px-4">Parent</th>
                    <th className="py-3 px-4">Description</th>
                    <th className="py-3 px-4 text-right">Actions</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100 dark:divide-slate-800/60 font-sans">
                  {categories.map(c => {
                    const status = c.status || 'published';
                    return (
                      <tr key={c._id} className="hover:bg-slate-50/50 dark:hover:bg-slate-900/30 transition-colors">
                        <td className="py-3.5 px-4 font-semibold text-slate-900 dark:text-white">
                          {c.name}
                        </td>
                        <td className="py-3.5 px-4 font-mono text-slate-500 text-[11px]">
                          {c.slug || '—'}
                        </td>
                        <td className="py-3.5 px-4 font-mono text-[11px]">
                          <span
                            className={
                              status === 'published'
                                ? 'text-emerald-600 dark:text-emerald-400 font-bold'
                                : status === 'draft'
                                ? 'text-amber-600 dark:text-amber-400 font-bold'
                                : 'text-slate-400'
                            }
                          >
                            {status}
                          </span>
                        </td>
                        <td className="py-3.5 px-4 font-mono tabular-nums text-slate-500">
                          {c.sortOrder ?? 0}
                        </td>
                        <td className="py-3.5 px-4 font-mono text-slate-400 text-[11px]">
                          {c.parentId || 'None'}
                        </td>
                        <td className="py-3.5 px-4 text-slate-500 dark:text-slate-400 max-w-xs truncate">
                          {c.description || '—'}
                        </td>
                        <td className="py-3.5 px-4 text-right">
                          {canManage && (
                            <button
                              type="button"
                              onClick={() => openEditModal(c)}
                              className="px-3 py-1.5 rounded-lg border border-slate-200 dark:border-slate-800 hover:bg-slate-100 dark:hover:bg-slate-900 text-slate-700 dark:text-slate-300 text-xs font-semibold inline-flex items-center gap-1 transition-colors"
                            >
                              <Edit2 size={12} />
                              <span>Edit</span>
                            </button>
                          )}
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      )}

      {/* Create / Edit Modal */}
      {modalMode && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-xs">
          <div className="w-full max-w-lg bg-white dark:bg-[#121418] rounded-3xl border border-slate-200 dark:border-slate-800 shadow-2xl p-6 sm:p-8">
            <div className="flex items-center justify-between pb-4 border-b border-slate-100 dark:border-slate-800">
              <h3 className="font-display text-lg font-bold text-slate-900 dark:text-white">
                {modalMode === 'create' ? 'Create New Category' : `Edit Category "${editingCategory?.name}"`}
              </h3>
              <button
                type="button"
                onClick={() => setModalMode(null)}
                className="text-slate-400 hover:text-slate-600 dark:hover:text-slate-200"
              >
                <X size={18} />
              </button>
            </div>

            {modalError && (
              <div className="mt-4 p-3 rounded-xl bg-rose-500/10 border border-rose-500/20 text-rose-600 dark:text-rose-400 text-xs flex items-center gap-2">
                <AlertCircle size={14} />
                <span>{modalError}</span>
              </div>
            )}

            <form onSubmit={handleSaveCategory} className="mt-6 space-y-4">
              <div>
                <label className="block text-[11px] font-semibold text-slate-600 dark:text-slate-400 uppercase tracking-wider mb-1">
                  Category Name *
                </label>
                <input
                  type="text"
                  required
                  value={categoryForm.name}
                  onChange={e => setCategoryForm(prev => ({ ...prev, name: e.target.value }))}
                  minLength={2}
                  maxLength={80}
                  placeholder="e.g. Quantitative Systems"
                  className="w-full px-3 py-2 rounded-xl bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-800 text-xs text-slate-900 dark:text-white"
                />
              </div>

              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="block text-[11px] font-semibold text-slate-600 dark:text-slate-400 uppercase tracking-wider mb-1">
                    Slug (Optional)
                  </label>
                  <input
                    type="text"
                    value={categoryForm.slug}
                    onChange={e => setCategoryForm(prev => ({ ...prev, slug: e.target.value }))}
                    placeholder="quantitative-systems"
                    className="w-full px-3 py-2 rounded-xl bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-800 text-xs text-slate-900 dark:text-white font-mono"
                  />
                </div>
                <div>
                  <label className="block text-[11px] font-semibold text-slate-600 dark:text-slate-400 uppercase tracking-wider mb-1">
                    Sort Order
                  </label>
                  <input
                    type="number"
                    value={categoryForm.sortOrder}
                    onChange={e => setCategoryForm(prev => ({ ...prev, sortOrder: parseInt(e.target.value, 10) || 0 }))}
                    className="w-full px-3 py-2 rounded-xl bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-800 text-xs text-slate-900 dark:text-white font-mono"
                  />
                </div>
              </div>

              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="block text-[11px] font-semibold text-slate-600 dark:text-slate-400 uppercase tracking-wider mb-1">
                    Visibility Status
                  </label>
                  <select
                    value={categoryForm.status}
                    onChange={e => setCategoryForm(prev => ({ ...prev, status: e.target.value as any }))}
                    className="w-full px-3 py-2 rounded-xl bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-800 text-xs text-slate-900 dark:text-white font-mono"
                  >
                    <option value="published">Published (Storefront Visible)</option>
                    <option value="draft">Draft (Hidden)</option>
                    <option value="archived">Archived (Retired)</option>
                  </select>
                </div>
                <div>
                  <label className="block text-[11px] font-semibold text-slate-600 dark:text-slate-400 uppercase tracking-wider mb-1">
                    Parent Category ID (Optional)
                  </label>
                  <input
                    type="text"
                    value={categoryForm.parentId}
                    onChange={e => setCategoryForm(prev => ({ ...prev, parentId: e.target.value }))}
                    placeholder="Existing parent category ID"
                    className="w-full px-3 py-2 rounded-xl bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-800 text-xs text-slate-900 dark:text-white font-mono"
                  />
                </div>
              </div>

              <div>
                <label className="block text-[11px] font-semibold text-slate-600 dark:text-slate-400 uppercase tracking-wider mb-1">
                  Description
                </label>
                <textarea
                  value={categoryForm.description}
                  onChange={e => setCategoryForm(prev => ({ ...prev, description: e.target.value }))}
                  rows={2}
                  maxLength={500}
                  placeholder="Short description of this category's catalog contents..."
                  className="w-full px-3 py-2 rounded-xl bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-800 text-xs text-slate-900 dark:text-white"
                />
              </div>

              <div className="flex items-center justify-end gap-3 pt-4 border-t border-slate-100 dark:border-slate-800">
                <button
                  type="button"
                  onClick={() => setModalMode(null)}
                  disabled={submittingModal}
                  className="px-4 py-2 rounded-xl border border-slate-200 dark:border-slate-800 text-xs font-semibold text-slate-600 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-900"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  disabled={submittingModal}
                  className="px-5 py-2 rounded-xl bg-teal-600 hover:bg-teal-500 text-white text-xs font-semibold inline-flex items-center gap-1.5 transition-colors disabled:opacity-50"
                >
                  {submittingModal && <Loader2 size={13} className="animate-spin" />}
                  <span>Save Category</span>
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default AdminCategories;
